Web Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Web Portal container

Container_Boundary(web_portal, "Web Portal") {
    Component(Patron_UI_SPA, "Patron UI SPA", "React / TypeScript", "Provides the user interface and client-side routing for library patrons to browse catalogues, manage loans, and access self-service portals.")
    Component(Staff_Dashboard_SPA, "Staff Dashboard SPA", "React / TypeScript", "Provides administrative and circulation control interfaces for staff and library administrators.")
    Component(Nginx_Web_Server, "Nginx Web Server", "Nginx on EU-restricted container", "Serves static assets and handles reverse proxying within an EU-restricted container deployment.")
}

Rel(Patron_UI_SPA, Nginx_Web_Server, "Routed and served through")
Rel(Staff_Dashboard_SPA, Nginx_Web_Server, "Routed and served through")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Routing_and_Edge_Router, "Routing and Edge Router", "Envoy/Kong", "Handles high-performance edge routing, rate limiting, and security termination.")
    Component(Authentication_and_OIDC_Validator, "Authentication & OIDC Validator", "Envoy/Kong Plugin / Lua", "Validates incoming tokens against the Identity Provider / SSO.")
    Component(gRPC_Upstream_Proxy, "gRPC Upstream Proxy", "Envoy/Kong Proxy", "Routes internal traffic securely to Core Services API and Search & Catalogue Service via gRPC over mTLS.")
}

Rel(Routing_and_Edge_Router, Authentication_and_OIDC_Validator, "Delegates token validation", "")
Rel(Routing_and_Edge_Router, gRPC_Upstream_Proxy, "Forwards validated requests", "")
@enduml

Search & Catalogue Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(search_catalogue_service, "Search & Catalogue Service") {
    Component(search_api_handler, "Search API Handler", "Java/Spring Boot", "Handles incoming search requests and routes them within the search service.")
    Component(query_builder_faceting_engine, "Query Builder & Faceting Engine", "Java", "Constructs complex search queries and manages faceting logic.")
    Component(indexing_worker, "Indexing Worker", "Java/Spring Boot", "Processes data streams and updates the search index.")
    Component(search_engine_index, "Search Engine Index", "OpenSearch", "Executes inverted-index queries for high-performance search.")
}

Rel(search_api_handler, query_builder_faceting_engine, "In-process method call", "")
Rel(query_builder_faceting_engine, search_engine_index, "REST over mTLS", "")
@enduml

Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database container

Container_Boundary(database_container, "Database") {
    Component(Connection_Pool___Session_Manager, "Connection Pool & Session Manager", "PgBouncer", "Manages and pools client database connections over TLS 1.3 to ensure high performance and EU data residency compliance.")
    Component(Relational_Data_Store, "Relational Data Store", "PostgreSQL with EU hosting", "Stores persistent relational data including patron records, circulation logs, and catalogue metadata with row/column encryption.")
}

Rel(Connection_Pool___Session_Manager, Relational_Data_Store, "Routes and multiplexes database queries over PostgreSQL Wire Protocol")

@enduml
